// gh-1027: per-tick scan budget for the conflict-rework rule.
//
// An already-reported DIRTY PR must not consume a rule-limit slot: gh-1025
// raised the limit 1 -> 5, which only pushed the starvation class out to
// 5+ parked markers (live 2026-10-18: fa #983 parked every tick behind its
// own marker while unreported PRs were never evaluated, each still costing
// a github_get_pr_comments fetch). The engine loop now scans candidates
// until `limit` ACTIONABLE (unreported) ones were processed, and this
// module bounds that scan so a long parked queue cannot fan the per-tick
// comments fetches without limit.
//
// Bounded, not eliminated (the same tradeoff gh-922's
// TRIGGER_FALLTHROUGH_RESERVE documents): parked markers beyond the budget
// ahead of the first unreported candidate re-starve one tick's slice —
// they drain as their rework legs land, so the bound only ever costs a
// tick of delay, never a deadlock.
//
// Shared by js/smAgent.js (the rule loop's break condition) and
// js/sm/sources/githubSource.js (queryPrs' candidate slice) — the two must
// agree, or the query slice re-cuts the queue before the loop ever sees
// the candidates behind the parked markers.
'use strict';

// Extra already-reported candidates a tick may scan past the rule limit.
var OVERSCAN = 15;

// Total candidates the conflict-rework rule may scan per tick for a given
// rule limit. A non-positive/invalid limit degrades to the overscan alone
// (callers with no rule limit are uncapped anyway and never consult this).
function scanLimit(limit) {
    var l = (typeof limit === 'number' && isFinite(limit) && limit > 0)
        ? Math.floor(limit) : 0;
    return l + OVERSCAN;
}

// queryPrs' candidate-slice cap (gh-1027 CRAP refactor): extracted from
// queryPrs so the conflict_rework branch doesn't compound the query
// function's complexity — the CRAP ratchet failed on queryPrs 67.4 -> 68.4
// because the ternary added a decision point the coverage could never buy
// back (CRAP floors at CC). conflict_rework widens to the shared over-scan
// budget; every other rule keeps the gh-922 fallthrough reserve (passed in
// so the TRIGGER_FALLTHROUGH_RESERVE constant stays at its githubSource
// home).
function sliceCap(rule, limit, fallthroughReserve) {
    if (rule && rule.localAction === 'conflict_rework') {
        return scanLimit(limit);
    }
    return limit + fallthroughReserve;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { OVERSCAN: OVERSCAN, scanLimit: scanLimit, sliceCap: sliceCap };
}

/* global loadModule, assert, test, suite, makeRequire */

// gh-1027: the shared over-scan budget (smAgent loop break + queryPrs slice
// must agree — a mismatch re-cuts the queue before the loop sees candidates
// parked behind already-reported markers).
suite('conflictReworkScan — scanLimit budget', function () {
    var mod = loadModule('js/common/conflictReworkScan.js', makeRequire({}), {});

    test('limit + OVERSCAN for positive limits', function () {
        assert.equal(mod.scanLimit(1), 16, 'limit 1 scans 16 candidates');
        assert.equal(mod.scanLimit(5), 20);
        assert.equal(mod.OVERSCAN, 15);
    });

    test('invalid limits degrade to the overscan alone', function () {
        assert.equal(mod.scanLimit(0), 15);
        assert.equal(mod.scanLimit(-3), 15);
        assert.equal(mod.scanLimit('x'), 15);
        assert.equal(mod.scanLimit(undefined), 15);
        assert.equal(mod.scanLimit(2.9), 17, 'floored');
    });
});

// gh-1027 rework (CRAP ratchet regression): the slice-cap branch was
// extracted from queryPrs into sliceCap — queryPrs' CC (and so its CRAP
// floor) must not carry the conflict_rework decision.
suite('conflictReworkScan — sliceCap query slice', function () {
    var mod = loadModule('js/common/conflictReworkScan.js', makeRequire({}), {});

    test('conflict_rework rules widen to the over-scan budget', function () {
        assert.equal(mod.sliceCap({ localAction: 'conflict_rework' }, 1, 3), 16,
            'limit 1 -> scanLimit(1) = 16');
        assert.equal(mod.sliceCap({ localAction: 'conflict_rework' }, 5, 3), 20);
        assert.equal(mod.sliceCap({ localAction: 'conflict_rework', limit: 5 }, 2.9, 3), 17,
            'invalid/fractional limit degrades to OVERSCAN alone');
    });

    test('other rules keep limit + fallthrough reserve', function () {
        assert.equal(mod.sliceCap({ localAction: 'validate_fresh' }, 1, 3), 4);
        assert.equal(mod.sliceCap({ localAction: 'validate_fresh' }, 5, 3), 8);
        assert.equal(mod.sliceCap({}, 1, 3), 4, 'rule without localAction keeps the reserve');
        assert.equal(mod.sliceCap(null, 2, 3), 5, 'null rule keeps the reserve');
        assert.equal(mod.sliceCap(undefined, 2, 3), 5, 'undefined rule keeps the reserve');
    });
});

