        // One rerun per RUN (a run re-stamps every context it
        // carries — two cancelled contexts from the same cancelled
        // run need a single gh run rerun, not two).
        var rcSeen = {};
        rcTargets.forEach(function (t) {
            if (rcSeen[t.runId]) return;
