+                items: items,
+                prComments: reportedMarkers(20)
+            }
+        });
+
+        sm.action(params([RULE_LIMIT5]));
+
+        assert.equal(sm.capturedPrComments.length, 0, 'position 21 is past the limit-5 over-scan budget (20) — waits one tick');
+    });
+});
